/**
 * Composes the release bundle `dist/my-package-1.0.0-release.zip` containing:
 *  - the npm pack tarball (dist/my-package-1.0.0.tgz)
 *  - the artifact hash manifest (dist/SHA256SUMS)
 *  - the SBOM (sbom.cdx.json)
 * Deterministic: fixed mtimes on all members, fixed compression level, sorted
 * entry order (zipfile adds no extra fields).
 * Usage: node scripts/make-release.js
 */
const { execSync } = require("child_process");
const fs = require("fs");

const TAR = "my-package-1.0.0.tgz";
const ZIP = "dist/my-package-1.0.0-release.zip";
const MEMBERS = [`dist/${TAR}`, "dist/SHA256SUMS", "sbom.cdx.json"];
const EPOCH = 946684800;

execSync("npm run build", { stdio: "inherit" });
execSync("npm run sbom", { stdio: "inherit" });

execSync(`sha256sum ${TAR} > SHA256SUMS`, { cwd: "dist" });

const epoch = new Date(EPOCH * 1000);
for (const f of MEMBERS) fs.utimesSync(f, epoch, epoch);

fs.rmSync(ZIP, { force: true });
execSync(
  `python3 ${__dirname}/make-release.py ${ZIP} ${MEMBERS.join(" ")}`,
  { env: { ...process.env, TZ: "UTC" } }
);

const zipHash = execSync(`sha256sum ${ZIP}`, { encoding: "utf8" }).trim();
console.log(zipHash);
